import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"SettingsRow","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/settings-row.md","filePath":"workbench/settings-row.md"}'),n={name:"workbench/settings-row.md"};function i(s,t,d,h,c,l){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="settingsrow" tabindex="-1">SettingsRow <a class="header-anchor" href="#settingsrow" aria-label="Permalink to &quot;SettingsRow&quot;">​</a></h1><p>SettingsRow is one setting: its name and description on the left and its control on the right.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it inside a <a href="./settings-section">SettingsSection</a>, one row for each setting. The application passes the control: a <a href="./../components/text-input">TextInput</a>, a <a href="./../components/toggle">Toggle</a> without a label of its own, a <a href="./../components/select">Select</a> or a button that starts an action, such as a danger button that opens a confirmation. Give the control&#39;s id in <code>for</code> so that the name labels it; a control without an id takes an accessible name of its own (<code>ariaLabel</code>). A setting of the thing selected, in a panel beside the stage, is an <a href="./inspector-row">InspectorRow</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>required</td><td>The name of the setting</td></tr><tr><td><code>description</code></td><td></td><td>One sentence under the name</td></tr><tr><td><code>for</code></td><td></td><td>The id of the control that the name labels</td></tr><tr><td><code>width</code></td><td></td><td>A fixed width for the control: <code>8rem</code>, <code>12rem</code> or <code>20rem</code></td></tr><tr><td><code>control</code></td><td></td><td>The control (a snippet); <code>children</code> serve the same</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The name is body text and the description a muted caption gap-xs below it; they are trimmed only where the row meets the edge of its section, as the first or the last row. The text takes the rest of the row and the control keeps its own width, or fills <code>width</code>, gap-lg from the text and level with the middle of the text. Below 48rem the control moves under the text, gap-sm from it, at the start. The row is a group named by the name and described by the description. Controls inside take a button&#39;s height.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/settings-row/" title="SettingsRow" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/settings-row/" target="_blank" rel="noopener">SettingsRow</a></figcaption></figure>',10)])])}const f=e(n,[["render",i]]);export{m as __pageData,f as default};
